import com.example.kilgi.inventory.engine.LandedCostCalculator;
import com.example.kilgi.inventory.engine.TrueCostPerKiloEngine;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class ProcurementBatchTest {

    @Test
    public void landedCost_sumsEveryProcurementCost() {
        double landedCost = LandedCostCalculator.calculateTotalLandedCost(5000, 300, 200, 150, 50);

        assertEquals(5700, landedCost, 0.0001);
    }

    @Test
    public void batch_calculatesInitialAndTrueCostPerKilo() {
        ProcurementBatch batch = createTomatoBatch();

        assertEquals(100, batch.getInitialWeightKg(), 0.0001);
        assertEquals(57, batch.getInitialCostPerKilo(), 0.0001);

        batch.logSpoilage(10, "Rotten tomatoes");

        assertEquals(10, batch.getTotalSpoilageWeightKg(), 0.0001);
        assertEquals(90, batch.getRemainingSellableWeightKg(), 0.0001);
        assertEquals(63.3333, batch.getTrueCostPerKilo(), 0.0001);
    }

    @Test
    public void batch_supportsMultipleSpoilageLogs() {
        ProcurementBatch batch = createTomatoBatch();

        batch.logSpoilage(5, "Bruised during unloading");
        batch.logSpoilage(new SpoilageEntry(7.5, "Overripe produce", 1720195200000L));

        assertEquals(12.5, batch.getTotalSpoilageWeightKg(), 0.0001);
        assertEquals(87.5, batch.getRemainingSellableWeightKg(), 0.0001);
        assertEquals(65.142857, batch.getTrueCostPerKilo(), 0.0001);
        assertEquals(2, batch.getSpoilageEntries().size());
    }

    @Test
    public void batch_rejectsSpoilageThatExceedsInventory() {
        ProcurementBatch batch = createTomatoBatch();

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> batch.logSpoilage(101, "Everything spoiled")
        );

        assertEquals("Total spoilage cannot exceed the batch weight.", exception.getMessage());
    }

    @Test
    public void trueCostEngine_requiresSellableWeight() {
        IllegalStateException exception = assertThrows(
                IllegalStateException.class,
                () -> TrueCostPerKiloEngine.calculate(5700, 0)
        );

        assertEquals("remainingSellableWeightKg must be greater than zero.", exception.getMessage());
    }

    @Test
    public void unitConversion_translatesWholesaleUnitsToKilograms() {
        UnitConversion unitConversion = new UnitConversion("crate", 22.5);

        assertEquals(67.5, unitConversion.toKilograms(3), 0.0001);
        assertEquals(1.333333, unitConversion.toUnits(30), 0.0001);
    }

    private ProcurementBatch createTomatoBatch() {
        return new ProcurementBatch(
                "Tomato",
                "Davao Growers Cooperative",
                4,
                new UnitConversion("sack", 25),
                5000,
                300,
                200,
                150,
                50
        );
    }
}

package com.example.kilgi.inventory.model;

/**
 * Converts a wholesale unit such as a sack or crate into kilograms.
 */
public class UnitConversion {

    private final String unitName;
    private final double kilogramsPerUnit;

    public UnitConversion(String unitName, double kilogramsPerUnit) {
        this.unitName = requireText(unitName, "unitName");
        if (kilogramsPerUnit <= 0) {
            throw new IllegalArgumentException("kilogramsPerUnit must be greater than zero.");
        }
        this.kilogramsPerUnit = kilogramsPerUnit;
    }

    public String getUnitName() {
        return unitName;
    }

    public double getKilogramsPerUnit() {
        return kilogramsPerUnit;
    }

    public double toKilograms(double unitCount) {
        validateNonNegative(unitCount, "unitCount");
        return unitCount * kilogramsPerUnit;
    }

    public double toUnits(double kilograms) {
        validateNonNegative(kilograms, "kilograms");
        return kilograms / kilogramsPerUnit;
    }

    private static void validateNonNegative(double value, String fieldName) {
        if (value < 0) {
            throw new IllegalArgumentException(fieldName + " cannot be negative.");
        }
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

package com.example.kilgi.inventory.model;

import java.util.List;

/**
 * Converts measured wholesale units such as sacks or crates into kilograms.
 *
 * <p>This model does not assume every sack has the same weight. Instead,
 * the batch provides the actual weight of each purchased unit.</p>
 */
public class UnitConversion {

    private final String unitName;

    public UnitConversion(String unitName) {
        this.unitName = requireText(unitName, "unitName");
    }

    public String getUnitName() {
        return unitName;
    }

    public double toKilograms(List<Double> unitWeightsKg) {
        validateUnitWeights(unitWeightsKg);

        double totalWeightKg = 0;
        for (Double weightKg : unitWeightsKg) {
            totalWeightKg += weightKg;
        }
        return totalWeightKg;
    }

    public double getAverageKilogramsPerUnit(List<Double> unitWeightsKg) {
        validateUnitWeights(unitWeightsKg);
        return toKilograms(unitWeightsKg) / unitWeightsKg.size();
    }

    public double toEstimatedUnits(double kilograms, List<Double> referenceUnitWeightsKg) {
        validateNonNegative(kilograms, "kilograms");
        return kilograms / getAverageKilogramsPerUnit(referenceUnitWeightsKg);
    }

    private static void validateNonNegative(double value, String fieldName) {
        if (value < 0) {
            throw new IllegalArgumentException(fieldName + " cannot be negative.");
        }
    }

    private static void validateUnitWeights(List<Double> unitWeightsKg) {
        if (unitWeightsKg == null || unitWeightsKg.isEmpty()) {
            throw new IllegalArgumentException("unitWeightsKg cannot be null or empty.");
        }

        for (Double weightKg : unitWeightsKg) {
            if (weightKg == null || weightKg <= 0) {
                throw new IllegalArgumentException("Each unit weight must be greater than zero.");
            }
        }
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}
